'use client';

import * as React from 'react';
import { Menu as BaseMenu } from '@base-ui/react/menu';
import { ContextMenu as BaseContextMenu } from '@base-ui/react/context-menu';
import { Kbd } from '../kbd/kbd';
import './menu.css';

/* ─────────────────────────────────────────────────────────
 * MENU and CORRECTION POPOVER (the brief, 04 §8, §18; the reference design's #pop) on Base UI Menu
 *   open      from a trigger (6 below it) or at the pointer (right-click): fades in on settle
 *   heading   what the menu acts on, engraved: "NOTE · TASK BY RECOGNIZER 0.82"
 *   rows      pointer and keyboard share one highlighted state; ↑ ↓ and type-ahead; ↩ chooses
 *   choose    the row runs and the menu closes (fades on release); focus returns to the trigger
 *   ⎋ / click outside  closes, nothing runs
 * ───────────────────────────────────────────────────────── */

function offset() {
  if (typeof window === 'undefined') return 6;
  return parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--mu-menu-offset')) || 6;
}

function Plate({ heading, children }: { heading?: string; children: React.ReactNode }) {
  return (
    <BaseMenu.Popup className="mu-menu">
      {heading ? (
        <BaseMenu.Group>
          <BaseMenu.GroupLabel className="mu-menu-heading mu-type-label">{heading}</BaseMenu.GroupLabel>
          {children}
        </BaseMenu.Group>
      ) : children}
    </BaseMenu.Popup>
  );
}

export interface MenuProps {
  /** The control that opens it. It must accept a ref and props (a Button, an icon button). */
  trigger: React.ReactElement;
  /** What the menu acts on, as an engraving above the rows. */
  heading?: string;
  side?: 'bottom' | 'top' | 'left' | 'right';
  align?: 'start' | 'center' | 'end';
  /** MenuItem and MenuSeparator. */
  children: React.ReactNode;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
}

/** A menu from a trigger: a frosted plate of rows 6 below it. */
export function Menu({ trigger, heading, side = 'bottom', align = 'start', children, open, onOpenChange }: MenuProps) {
  return (
    <BaseMenu.Root open={open} onOpenChange={onOpenChange ? (o) => onOpenChange(o) : undefined}>
      <BaseMenu.Trigger render={trigger} />
      <BaseMenu.Portal>
        <BaseMenu.Positioner className="mu-menu-positioner" side={side} align={align} sideOffset={offset()} collisionPadding={8}>
          <Plate heading={heading}>{children}</Plate>
        </BaseMenu.Positioner>
      </BaseMenu.Portal>
    </BaseMenu.Root>
  );
}

export interface ContextMenuProps {
  /** The rows: MenuItem and MenuSeparator. */
  menu: React.ReactNode;
  /** What the menu acts on: for a correction, the cue's provenance. */
  heading?: string;
  /** The area that answers a right-click (or ⌃-click, or a long press). */
  children: React.ReactElement;
}

/**
 * The correction popover: right-click a cue (or anything) for a menu at the pointer. Corrections win
 * and are remembered; the host shows a toast with Undo after one.
 */
export function ContextMenu({ menu, heading, children }: ContextMenuProps) {
  return (
    <BaseContextMenu.Root>
      <BaseContextMenu.Trigger render={children} />
      <BaseContextMenu.Portal>
        <BaseContextMenu.Positioner className="mu-menu-positioner" collisionPadding={8}>
          <Plate heading={heading}>{menu}</Plate>
        </BaseContextMenu.Positioner>
      </BaseContextMenu.Portal>
    </BaseContextMenu.Root>
  );
}

export interface MenuItemProps {
  /** Runs when chosen (click, ↩, or a release after press-and-drag). */
  onSelect?: () => void;
  /** The 14 glyph at the left. */
  icon?: React.ReactNode;
  /** The key at the right: "⌘Z". */
  shortcut?: string;
  /** A destructive action: red. */
  danger?: boolean;
  disabled?: boolean;
  children: React.ReactNode;
}

/** A 30 row. */
export function MenuItem({ onSelect, icon, shortcut, danger, disabled, children }: MenuItemProps) {
  return (
    <BaseMenu.Item className="mu-menu-row mu-type-ui mu-icon-trigger" onClick={onSelect} disabled={disabled} data-danger={danger ? '' : undefined}>
      {icon && <span aria-hidden className="mu-menu-glyph">{icon}</span>}
      <span className="mu-menu-label">{children}</span>
      {shortcut && <Kbd size="small" className="mu-menu-key">{shortcut}</Kbd>}
    </BaseMenu.Item>
  );
}

/** An engraved rule between groups of rows. */
export function MenuSeparator() {
  return <BaseMenu.Separator className="mu-menu-sep" />;
}

@import "../tokens.css";

/* Menu and the correction popover (the reference design's #pop) on Base UI Menu. Its look is the menu recipe (--mu-r-menu-*). */
/* Above a toast: a menu is what the person is acting in now. */
.mu-menu-positioner { z-index: var(--mu-r-menu-self-z); }
.mu-menu {
  min-width: var(--mu-r-menu-self-min-width);
  padding: var(--mu-r-menu-self-pad);
  border-radius: var(--mu-r-menu-self-radius);
  outline: var(--mu-zero);
  background: var(--mu-r-menu-self-background);
  box-shadow: var(--mu-r-menu-self-shadow);
  -webkit-backdrop-filter: var(--mu-r-menu-self-blur);
  backdrop-filter: var(--mu-r-menu-self-blur);
  transform-origin: var(--transform-origin);
  /* A fade on settle, out on release: a menu appears where it is, it does not travel. */
  transition: opacity var(--mu-spring-settle-d) var(--mu-spring-settle);
}
.mu-menu[data-starting-style], .mu-menu[data-ending-style] { opacity: var(--mu-zero); }
.mu-menu[data-ending-style] { transition: opacity var(--mu-spring-release-d) var(--mu-spring-release); }
.mu-menu-heading {
  padding: var(--mu-r-menu-heading-pad-top) var(--mu-r-menu-heading-pad-x) var(--mu-r-menu-heading-pad-bottom);
  color: var(--mu-engrave);
  text-shadow: var(--mu-lip-shadow);
}
.mu-menu-row {
  display: flex;
  align-items: center;
  gap: var(--mu-r-menu-row-gap);
  height: var(--mu-r-menu-row-height);
  padding: var(--mu-zero) var(--mu-r-menu-row-pad);
  border-radius: var(--mu-r-menu-row-radius);
  font: var(--mu-r-menu-row-font);
  letter-spacing: var(--mu-r-menu-row-tracking);
  color: var(--mu-ink);
  cursor: default;
  outline: var(--mu-zero);
  user-select: none;
}
.mu-menu-glyph { display: inline-grid; flex: none; color: var(--mu-ink2); }
.mu-menu-glyph > svg { width: var(--mu-r-menu-row-glyph); height: var(--mu-r-menu-row-glyph); }
.mu-menu-label { flex: 1; min-width: var(--mu-zero); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.mu-menu-key { margin-left: var(--mu-r-menu-row-key-gap); }
/* Pointer and keyboard share one highlighted state. Instant: a menu is scanned. */
.mu-menu-row[data-highlighted] { background: var(--mu-r-menu-row-hover-background); }
.mu-menu-row[data-danger], .mu-menu-row[data-danger] .mu-menu-glyph { color: var(--mu-red); }
.mu-menu-row[data-disabled] { opacity: var(--mu-r-menu-row-disabled); }
.mu-menu-sep {
  height: var(--mu-r-menu-sep-thickness);
  margin: var(--mu-r-menu-sep-inset-y) var(--mu-r-menu-sep-inset-x);
  background: var(--mu-r-menu-sep-background);
  box-shadow: var(--mu-r-menu-sep-shadow);
}
@media (prefers-reduced-transparency: reduce) {
  .mu-menu { background: var(--mu-frost-opaque); -webkit-backdrop-filter: none; backdrop-filter: none; }
}
